 void count_reject(ValidationCode c){if(c==ValidationCode::DUPLICATE_REVISION)m_.duplicate_peer_claims_rejected++;else if(c==ValidationCode::STALE_REVISION)m_.stale_peer_claims_rejected++;else if(c==ValidationCode::RETIRED_SESSION)m_.retired_session_messages_rejected++;else if(c==ValidationCode::CONCURRENT_SESSION)m_.concurrent_session_messages_rejected++;else m_.invalid_peer_claims_rejected++;}
