 void step(){double t=steady();if(peer_was_fresh_&&peer_->expired(t)){m_.peer_claim_expirations++;peer_was_fresh_=false;}if(core_.state==InternalState::WAITING_FOR_INPUTS){if(!autostart_)return;if(!latest_||t-candidate_received_>require_fresh_candidate_age_s_||!nav_->action_server_is_ready()){if(latest_&&t-candidate_received_>require_fresh_candidate_age_s_)m_.stale_candidate_batches++;return;}transition(InternalState::IDLE);}if(core_.state==InternalState::IDLE)create_proposal();else if(core_.state==InternalState::ARBITRATING){if(t-last_heartbeat_>=1./claim_heartbeat_rate_hz_){publish_claim(Claim::PROPOSING,"arbitrating");last_heartbeat_=t;}if(t-proposal_started_>=arbitration_window_s_){auto pc=peer_->claim(t);auto a=pc?arbitrate(*current_,*pc,equivalent_frontier_centroid_tolerance_m_,equivalent_frontier_bbox_margin_m_,path_cost_tie_tolerance_m_,true):ArbitrationResult::NO_CONFLICT;if(a==ArbitrationResult::PEER_WINS){m_.arbitration_losses++;release(false,"arbitration_lost");}else{m_.arbitration_wins++;dispatch();}}}else if(core_.state==InternalState::NAVIGATING){if(t-last_heartbeat_>=1./claim_heartbeat_rate_hz_){publish_claim(Claim::NAVIGATING,"navigating");last_heartbeat_=t;}if(!cancel_pending_&&t-accepted_at_>=navigation_goal_timeout_s_){m_.navigation_timeouts++;request_cancel("navigation_timeout");}if(cancel_pending_&&t-cancel_requested_at_>=cancellation_ack_timeout_s_){m_.cancellation_ack_timeouts++;goal_.reset();m_.navigation_failures++;begin_terminal(Claim::FAILED,cancel_reason_+"_ack_timeout");}}else if(core_.state==InternalState::TERMINAL_BROADCAST){if(t-last_terminal_>=1./terminal_broadcast_rate_hz_){publish_claim(terminal_state_,terminal_reason_);last_terminal_=t;}if(t-terminal_started_>=terminal_broadcast_duration_s_)finish_terminal();}if(t-last_diag_>=5){diag();last_diag_=t;}}
 void diag(){RCLCPP_INFO(get_logger(),"COORD_METRICS state=%d ext=%u claim=%lu session=%s peer_session=%s peer_age=%.3f proposals=%u pub=%lu peer_ok=%lu conflicts=%lu wins=%lu losses=%lu releases=%lu goals_sent=%lu goals_accepted=%lu success=%lu fail=%lu cancel=%lu budget=%d",int(core_.state),current_?current_->state:0,current_?current_->claim_id:0,uuid_key(session_).c_str(),peer_->active_key().c_str(),peer_->age(steady()),core_.proposals,m_.claims_published,m_.peer_claims_accepted,m_.conflicts_detected,m_.arbitration_wins,m_.arbitration_losses,m_.proposal_releases,m_.navigation_goals_sent,m_.navigation_goals_accepted,m_.navigation_successes,m_.navigation_failures,m_.navigation_cancellations,core_.budget_consumed);}
